class Solution{public:bool judgePoint24(vector<int>a){if(a.size()==1)return abs(a[0]-24)<1e-6;for(int i=0;i<a.size();i++)for(int j=i+1;j<a.size();j++){vector<double>b;for(int k=0;k<a.size();k++)if(k!=i&&k!=j)b.push_back(a[k]);vector<double>x={a[i]+a[j],a[i]-a[j],a[j]-a[i],a[i]*a[j]};if(a[j])x.push_back((double)a[i]/a[j]);if(a[i])x.push_back((double)a[j]/a[i]);for(double y:x){b.push_back(y);if(judge(b))return true;b.pop_back();}}return false;}private:bool judge(vector<double>a){if(a.size()==1)return fabs(a[0]-24)<1e-6;for(int i=0;i<a.size();i++)for(int j=i+1;j<a.size();j++){vector<double>b;for(int k=0;k<a.size();k++)if(k!=i&&k!=j)b.push_back(a[k]);vector<double>x={a[i]+a[j],a[i]-a[j],a[j]-a[i],a[i]*a[j]};if(a[j])x.push_back(a[i]/a[j]);if(a[i])x.push_back(a[j]/a[i]);for(double y:x){b.push_back(y);if(judge(b))return true;b.pop_back();}}return false;}};
